          target,
          graphBuilder,
          graphBuilder.getSourcePathResolver(),
          CxxPlatformUtils.DEFAULT_CONFIG,
          cxxPlatform,
          ImmutableList.of(),
          ImmutableMultimap.of(),
          Optional.empty(),
          Optional.empty(),
          PicType.PDC);

  // Check that link rule has the expected deps: the object files for our sources and the
  // archive from the dependency.
  assertEquals(
      ImmutableSet.of(
          cxxSourceRuleFactory.createCompileBuildTarget("test/bar.cpp"),
          cxxSourceRuleFactory.createCompileBuildTarget(genSourceName),
          archiveTarget),
      rule.getBuildDeps().stream()
          .map(BuildRule::getBuildTarget)
          .collect(ImmutableSet.toImmutableSet()));

  // Verify that the compile rule for our user-provided source has correct deps setup
  // for the various header rules.
  BuildRule compileRule1 =
      graphBuilder.getRule(cxxSourceRuleFactory.createCompileBuildTarget("test/bar.cpp"));
  assertNotNull(compileRule1);
  assertThat(
      DependencyAggregationTestUtil.getDisaggregatedDeps(compileRule1)
          .map(BuildRule::getBuildTarget)
          .collect(ImmutableSet.toImmutableSet()),
      Matchers.containsInAnyOrder(
          genHeaderTarget,
          headerSymlinkTreeTarget,
          CxxDescriptionEnhancer.createHeaderSymlinkTreeTarget(
              target, HeaderVisibility.PRIVATE, cxxPlatform.getFlavor())));

  // Verify that the compile rule for our genrule-generated source has correct deps setup
  // for the various header rules and the generating genrule.
  BuildRule compileRule2 =
      graphBuilder.getRule(cxxSourceRuleFactory.createCompileBuildTarget(genSourceName));
  assertNotNull(compileRule2);
  assertThat(
      DependencyAggregationTestUtil.getDisaggregatedDeps(compileRule2)
          .map(BuildRule::getBuildTarget)
          .collect(ImmutableList.toImmutableList()),
      Matchers.containsInAnyOrder(
          genHeaderTarget,
          genSourceTarget,
          headerSymlinkTreeTarget,
          CxxDescriptionEnhancer.createHeaderSymlinkTreeTarget(
              target, HeaderVisibility.PRIVATE, cxxPlatform.getFlavor())));
}

public void testGetMatchingBuildTargets() {
  BuildTarget prebuiltJarTarget = BuildTargetFactory.newInstance("//empty:empty");
  TargetNode<?> prebuiltJarNode =
      PrebuiltJarBuilder.createBuilder(prebuiltJarTarget)
          .setBinaryJar(Paths.get("spoof"))
          .build();

  BuildTarget javaLibraryTarget = BuildTargetFactory.newInstance("//javasrc:java-library");
  TargetNode<?> javaLibraryNode =
      JavaLibraryBuilder.createBuilder(javaLibraryTarget)
          .addSrc(Paths.get("javasrc/JavaLibrary.java"))
          .addDep(prebuiltJarTarget)
          .build();

  BuildTarget javaTestTarget = BuildTargetFactory.newInstance("//javatest:test-java-library");
  TargetNode<?> javaTestNode =
      JavaTestBuilder.createBuilder(javaTestTarget)
          .addSrc(Paths.get("javatest/TestJavaLibrary.java"))
          .addDep(javaLibraryTarget)
          .build();

  ImmutableSet<TargetNode<?>> nodes =
      ImmutableSet.of(prebuiltJarNode, javaLibraryNode, javaTestNode);

  TargetGraph targetGraph = TargetGraphFactory.newInstance(nodes);

  ImmutableSet<RelPath> referencedFiles;

  // No target depends on the referenced file.
  referencedFiles = ImmutableSet.of(RelPath.get("excludesrc/CannotFind.java"));
  SortedMap<String, TargetNode<?>> matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.of(referencedFiles),
          Optional.empty(),
          Optional.empty(),
          false,
          "BUCK",
          filesystem);
  assertTrue(matchingBuildRules.isEmpty());

  // Only test-android-library target depends on the referenced file.
  referencedFiles = ImmutableSet.of(RelPath.get("javatest/TestJavaLibrary.java"));
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.of(referencedFiles),
          Optional.empty(),
          Optional.empty(),
          false,
          "BUCK",
          filesystem);
  assertEquals(ImmutableSet.of("//javatest:test-java-library"), matchingBuildRules.keySet());

  // The test-android-library target indirectly depends on the referenced file,
  // while test-java-library target directly depends on the referenced file.
  referencedFiles = ImmutableSet.of(RelPath.get("javasrc/JavaLibrary.java"));
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.of(referencedFiles),
          Optional.empty(),
          Optional.empty(),
          false,
          "BUCK",
          filesystem);
  assertEquals(
      ImmutableSet.of("//javatest:test-java-library", "//javasrc:java-library"),
      matchingBuildRules.keySet());

  // Verify that BUCK files show up as referenced files.
  referencedFiles = ImmutableSet.of(RelPath.get("javasrc/BUCK"));
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.of(referencedFiles),
          Optional.empty(),
          Optional.empty(),
          false,
          "BUCK",
          filesystem);
  assertEquals(
      ImmutableSet.of("//javatest:test-java-library", "//javasrc:java-library"),
      matchingBuildRules.keySet());

  // Output target only need to depend on one referenced file.
  referencedFiles =
      ImmutableSet.of(
          RelPath.get("javatest/TestJavaLibrary.java"), RelPath.get("othersrc/CannotFind.java"));
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.of(referencedFiles),
          Optional.empty(),
          Optional.empty(),
          false,
          "BUCK",
          filesystem);
  assertEquals(ImmutableSet.of("//javatest:test-java-library"), matchingBuildRules.keySet());

  // If no referenced file, means this filter is disabled, we can find all targets.
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.empty(),
          Optional.empty(),
          Optional.empty(),
          false,
          "BUCK",
          filesystem);
  assertEquals(
      ImmutableSet.of("//javatest:test-java-library", "//javasrc:java-library", "//empty:empty"),
      matchingBuildRules.keySet());

  // Specify java_test, java_library as type filters.
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.empty(),
          Optional.empty(),
          Optional.of(ImmutableSet.of(JavaTestDescription.class, JavaLibraryDescription.class)),
          false,
          "BUCK",
          filesystem);
  assertEquals(
      ImmutableSet.of("//javatest:test-java-library", "//javasrc:java-library"),
      matchingBuildRules.keySet());

  // Specify java_test, java_library, and a rule name as type filters.
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.empty(),
          Optional.of(ImmutableSet.of(BuildTargetFactory.newInstance("//javasrc:java-library"))),
          Optional.of(ImmutableSet.of(JavaTestDescription.class, JavaLibraryDescription.class)),
          false,
          "BUCK",
          filesystem);
  assertEquals(ImmutableSet.of("//javasrc:java-library"), matchingBuildRules.keySet());

  // Only filter by BuildTarget
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.empty(),
          Optional.of(ImmutableSet.of(BuildTargetFactory.newInstance("//javasrc:java-library"))),
          Optional.empty(),
          false,
          "BUCK",
          filesystem);
  assertEquals(ImmutableSet.of("//javasrc:java-library"), matchingBuildRules.keySet());

  // Filter by BuildTarget and Referenced Files
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.of(ImmutableSet.of(RelPath.get("javatest/TestJavaLibrary.java"))),
          Optional.of(ImmutableSet.of(BuildTargetFactory.newInstance("//javasrc:java-library"))),
          Optional.empty(),
          false,
          "BUCK",
          filesystem);
  assertEquals(ImmutableSet.<String>of(), matchingBuildRules.keySet());
}

