      }
    }

    // Make sure it's still possible to do work.
    throwWhileParsing.set(false);
    Futures.allAsList(scheduleWork(cell.getRootCell(), parserPool, executorService, 5)).get();
  } finally {
    executorService.shutdown();
  }
}

