public void testSameValueProxy() {
    byte[] bytecodes = new byte[]{
                    /* 0: */Bytecode.CONST,
                    /* 1: */42,
                    /* 2: */Bytecode.CONST,
                    /* 3: */-2,
                    /* 4: */Bytecode.CONST,
                    /* 5: */1,
                    /* 6: */Bytecode.ADD,
                    /* 7: */Bytecode.DUP,
                    /* 8: */Bytecode.CONST,
                    /* 9: */-2,
                    /* 10: */Bytecode.CONST,
                    /* 11: */1,
                    /* 12: */Bytecode.ADD,
                    /* 13: */Bytecode.DUP,
                    /* 14: */Bytecode.IFZERO,
                    /* 15: */18,
                    /* 16: */Bytecode.JMP,
                    /* 17: */10,
                    /* 18: */Bytecode.POP,
                    /* 19: */Bytecode.IFZERO,
                    /* 20: */23,
                    /* 21: */Bytecode.JMP,
                    /* 22: */4,
                    /* 23: */Bytecode.POP,
                    /* 24: */Bytecode.RETURN};

    CallTarget callee = ProxySameValueOnce.create("proxyAtStateProgram", bytecodes, 0, 6).getCallTarget();
    ProxySameValueOnce.SideEffect = -1;
    callee.call();
    ProxySameValueOnce.SideEffect = 0;
    callee.call();
    ProxySameValueOnce.SideEffect = 1;
    callee.call();
    callee.call();

    partialEval((OptimizedCallTarget) callee);

}

