public void visitWhileLoop(WhileLoop loop) {

code_after:
BytecodeLabel oldBreakLabel = currentBreakLabel;

b.beginBlock();
currentBreakLabel = b.createLabel();

b.beginWhile();
loop.condition.accept(this);
