  int maxBuckets = 128;
  final int bufferSize = (keySize + aggSize) * maxBuckets;
  final ByteBuffer buffer = ByteBuffer.wrap(new byte[bufferSize]);
  final HashVectorGrouper grouper = new HashVectorGrouper(
      Suppliers.ofInstance(buffer),
      keySize,
      aggregatorAdapters,
      maxBuckets,
      0.f,
