public void accessFieldsOfJavaObjectWithConverter() {
    Source src = Source.newBuilder("js", "" +
        "(function(t) {\n" +
        "  return 3600 * t.hours + 60 * t.minutes + t.seconds;\n" +
        "})\n",
        "MomentToSeconds.js").buildLiteral();

    final Moment javaMoment = new Moment(6, 30, 10);

