    objectsC.addAll(objectsA);
    validate(profiler, objectsC);

    /* Keep all objects alive. */
    GraalDirectives.blackhole(objectsA);
    GraalDirectives.blackhole(objectsB);
    GraalDirectives.blackhole(objectsC);
}

