        checker.destroy();
        assertWithMessage("Exception did not happen").fail();
    }
    catch (IllegalStateException ex) {
        assertWithMessage("Cause of exception differs from IOException")
                .that(ex.getCause())
                .isInstanceOf(IOException.class);
