@Test public void literalHeaderFieldWithoutIndexingIndexedName() throws IOException {
  List<Header> headerBlock = headerEntries(":path", "/sample/path");

  bytesIn.writeByte(0x04); // == Literal not indexed ==
  // Indexed name (idx = 4) -> :path
