  hpackWriter.writeHeaders(headerBlock);
  assertEquals(bytesIn, bytesOut);

  hpackReader.readHeaders();

  assertEquals(0, hpackReader.dynamicTableHeaderCount);

  assertEquals(headerBlock, hpackReader.getAndResetHeaderList());
}

