  List<String> expectedMessages = Arrays.asList(
      "Unable to parse malformed data during iterator construction",
      "Unable to parse malformed data during iterator construction"
  );
  Assert.assertEquals(expectedMessages, parseExceptionReport.getErrorMessages());
}

