public void testDisjointTreeFromHackerrank() {
  // https://www.hackerearth.com/practice/algorithms/graphs/strongly-connected-components/tutorial
  int n = 16; // node 0 not used since these are 1 based
  List<List<Integer>> g = createGraph(n);

  addEdge(g, 3, 1);
  addEdge(g, 12, 11);
  addEdge(g, 10, 9);
  addEdge(g, 8, 5);
  addEdge(g, 1, 12);
  addEdge(g, 10, 2);
  addEdge(g, 1, 14);
  addEdge(g, 7, 9);
  addEdge(g, 10, 13);
  addEdge(g, 11, 1);
  addEdge(g, 6, 5);
  addEdge(g, 1, 15);
  addEdge(g, 2, 11);
  addEdge(g, 2, 6);
  addEdge(g, 9, 11);

  TarjanSccSolverAdjacencyList solver = new TarjanSccSolverAdjacencyList(g);
  solver.solve();

  List<List<Integer>> expectedSccs =
      ImmutableList.of(
          ImmutableList.of(0),
          ImmutableList.of(2),
          ImmutableList.of(3),
          ImmutableList.of(4),
          ImmutableList.of(5),
          ImmutableList.of(6),
          ImmutableList.of(7),
          ImmutableList.of(8),
          ImmutableList.of(9),
          ImmutableList.of(10),
          ImmutableList.of(1, 11, 12),
          ImmutableList.of(13),
          ImmutableList.of(14),
          ImmutableList.of(15));

  assertThat(solver.sccCount()).isEqualTo(expectedSccs.size());
  assertThat(isScc(solver.getSccs(), expectedSccs)).isTrue();
}

