  verifySystemSchemaQuery(
      datasourceAndSysUserClient,
      SYS_SCHEMA_SEGMENTS_QUERY,
      adminSegments.stream()
                   .filter((segmentEntry) -> "auth_test".equals(segmentEntry.get("datasource")))
                   .collect(Collectors.toList())
