public void testBooleanAnd() {
    Object foo = new Object();

    // foo -> true
    BytecodeNodeWithShortCircuit root = parseNode(b -> {
        b.beginRoot();
        b.beginReturn();
        b.beginBoolAnd();
        b.emitLoadConstant(foo);
        b.endBoolAnd();
        b.endReturn();
        b.endRoot();
    });
    assertEquals(true, root.getCallTarget().call());

    // 0 -> false
    root = parseNode(b -> {
        b.beginRoot();
        b.beginReturn();
        b.beginBoolAnd();
        b.emitLoadConstant(0);
        b.endBoolAnd();
        b.endReturn();
        b.endRoot();
    });
    assertEquals(false, root.getCallTarget().call());

    // true && 123 && foo -> true
    root = parseNode(b -> {
        b.beginRoot();
        b.beginReturn();
        b.beginBoolAnd();
        b.emitLoadConstant(true);
        b.emitLoadConstant(123);
        b.emitLoadConstant(foo);
        b.endBoolAnd();
        b.endReturn();
        b.endRoot();
    });
    assertEquals(true, root.getCallTarget().call());

    // true && 0 && foo -> false
    root = parseNode(b -> {
        b.beginRoot();
        b.beginReturn();
        b.beginBoolAnd();
        b.emitLoadConstant(true);
        b.emitLoadConstant(0);
        b.emitLoadConstant(foo);
        b.endBoolAnd();
        b.endReturn();
        b.endRoot();
    });
    assertEquals(false, root.getCallTarget().call());
}

