                    /* 16: */Bytecode.IFZERO,
                    /* 17: */3,

                    /* 18: */Bytecode.CONST,
                    /* 19: */1,
                    /* 20: */Bytecode.IFZERO,
                    /* 21: */18,

                    /* 22: */Bytecode.CONST,
                    /* 23: */42,
                    /* 24: */Bytecode.RETURN};
    assertPartialEvalEqualsAndRunsCorrect(Program.create("irreducibleLoop03", bytecodes, 3));
}

