    // Read Only
    IOAccess ioAccess;
    accessibleDir = createContent(Files.createTempDirectory(FileSystemsTest.class.getSimpleName()),
                    fullIO);
    ioAccess = IOAccess.newBuilder().fileSystem(FileSystem.newReadOnlyFileSystem(fullIO)).build();
