  Assert.assertEquals(
      ClientCompactionIntervalSpec.fromSegments(datasourceToSegments.get(dataSource), Granularities.YEAR),
      taskPayload.getIoConfig().getInputSpec()
  );

  ClientCompactionTaskGranularitySpec expectedGranularitySpec =
