        assertThat(task.getId()).isEqualTo(task1.getId());

        task = taskService.createTaskQuery().processInstanceBusinessKeyLikeIgnoreCase("%|_%").singleResult();
        assertThat(task).isNotNull();
        assertThat(task.getId()).isEqualTo(task2.getId());

