    for (TestAccessMode am : testAccessModesOfType(TestAccessType.GET_AND_SET)) {
        // Incorrect argument types
        checkNPE(() -> { // null array
            float x = (float) hs.get(am, methodType(float.class, float[].class, int.class, float.class)).
