    checkNPE(() -> { // null receiver
        int x = (int) vh.get(null);
    });
    checkCCE(() -> { // receiver reference class
        int x = (int) vh.get(Void.class);
    });
    checkWMTE(() -> { // receiver primitive class
        int x = (int) vh.get(0);
    });
    // Incorrect return type
    checkWMTE(() -> { // reference class
