    for (int i = 0; i < ITER-2; i+=2) {
        // Unrolled, with some swaps that prevent vectorization.
        out[i+0] += ((sArr1[2*i+0] * sArr2[2*i+0]) + (sArr1[2*i+1] * sArr2[2*i+1])); // ok
        out[i+1] += ((sArr1[2*i+2] * sArr2[2*i+3]) + (sArr1[2*i+3] * sArr2[2*i+2])); // bad
    }
    return out;
}

