    assertResultsPresentInDataResponse(url, id);

    url = CmmnRestUrls.createRelativeResourceUrl(CmmnRestUrls.URL_HISTORIC_CASE_INSTANCES) + "?activePlanItemDefinitionId=task1";
    assertResultsPresentInDataResponse(url);
}

