public void testIntToShortCoercion(RUN_TYPE runType) {
    // DROOLS-5939
    String str =
            "import " + ClassWithShortProperty.class.getCanonicalName() + ";\n" +
            "import " + ClassWithIntProperty.class.getCanonicalName() + ";\n" +
            "\n" +
