                "    END LOOP inner_loop;\n" +
                "  END LOOP outer_loop;\n" +
                "  DBMS_OUTPUT.PUT_LINE\n" +
                "    ('The sum of products equals: ' || TO_CHAR(s));\n" +
                "END;"; //

        List<SQLStatement> stmtList = SQLUtils.parseStatements(sql, JdbcConstants.ORACLE);
