    });
    // Incorrect return type
    checkWMTE(() -> { // reference class
        Void x = (Void) vh.get(recv);
    });
    checkWMTE(() -> { // primitive class
        boolean x = (boolean) vh.get(recv);
    });
    // Incorrect arity
    checkWMTE(() -> { // 0
