public void test_0() throws Exception {
    String sql = "CREATE TABLE employees ( " //
            + "id INT NOT NULL, " //
            + "fname VARCHAR(30), " //
            + "lname VARCHAR(30), " //
            + "hired DATE NOT NULL DEFAULT '1970-01-01', " //
            + "separated DATE NOT NULL DEFAULT '9999-12-31', " //
            + "job_code INT, store_id INT " //
            + ") PARTITION BY RANGE (YEAR(separated)) ( " //
            + "PARTITION p0 VALUES LESS THAN (1991), " //
            + "PARTITION p1 VALUES LESS THAN (1996), "
            + "PARTITION p2 VALUES LESS THAN (2001), "
            + "PARTITION p3 VALUES LESS THAN MAXVALUE )"; //

    MySqlStatementParser parser = new MySqlStatementParser(sql);
    List<SQLStatement> stmtList = parser.parseStatementList();
    SQLStatement stmt = stmtList.get(0);

    {
        String result = SQLUtils.toMySqlString(stmt);
        Assert.assertEquals("CREATE TABLE employees ("
                        + "\n\tid INT NOT NULL,"
                        + "\n\tfname VARCHAR(30),"
                        + "\n\tlname VARCHAR(30),"
                        + "\n\thired DATE NOT NULL DEFAULT '1970-01-01',"
                        + "\n\tseparated DATE NOT NULL DEFAULT '9999-12-31',"
                        + "\n\tjob_code INT,"
                        + "\n\tstore_id INT"
                        + "\n)"
                        + "\nPARTITION BY RANGE (YEAR(separated)) ("
                        + "\n\tPARTITION p0 VALUES LESS THAN (1991),"
                        + "\n\tPARTITION p1 VALUES LESS THAN (1996),"
                        + "\n\tPARTITION p2 VALUES LESS THAN (2001),"
                        + "\n\tPARTITION p3 VALUES LESS THAN MAXVALUE"
                        + "\n)",
                result);
    }
    {
        String result = SQLUtils.toMySqlString(stmt, SQLUtils.DEFAULT_LCASE_FORMAT_OPTION);
        Assert.assertEquals("create table employees ("
                        + "\n\tid INT not null,"
                        + "\n\tfname VARCHAR(30),"
                        + "\n\tlname VARCHAR(30),"
                        + "\n\thired DATE not null default '1970-01-01',"
                        + "\n\tseparated DATE not null default '9999-12-31',"
                        + "\n\tjob_code INT,"
                        + "\n\tstore_id INT"
                        + "\n)"
                        + "\npartition by range (YEAR(separated)) ("
                        + "\n\tpartition p0 values less than (1991),"
                        + "\n\tpartition p1 values less than (1996),"
                        + "\n\tpartition p2 values less than (2001),"
                        + "\n\tpartition p3 values less than maxvalue"
                        + "\n)",
                result);
    }

    Assert.assertEquals(1, stmtList.size());

    MySqlSchemaStatVisitor visitor = new MySqlSchemaStatVisitor();
    stmt.accept(visitor);

    System.out.println("Tables : " + visitor.getTables());
    System.out.println("fields : " + visitor.getColumns());
    System.out.println("coditions : " + visitor.getConditions());
    System.out.println("orderBy : " + visitor.getOrderByColumns());

    Assert.assertEquals(1, visitor.getTables().size());
    Assert.assertEquals(7, visitor.getColumns().size());
    Assert.assertEquals(0, visitor.getConditions().size());

    // Assert.assertTrue(visitor.getTables().containsKey(new TableStat.Name("t_basic_store")));

}

