    filters.clear();
    FilterManager.loadFilter(filters, filterItem);
    filterConfig = filters.get(0);
    Assert.assertNotNull(filterConfig);
    Assert.assertEquals("com.alibaba.druid.filter.stat.StatFilter", filterConfig.getClass().getName());
    // commonLogging
