static void testArrayWrongMethodType(VarHandle vh) throws Throwable {
    int[] array = new int[10];
    Arrays.fill(array, 0x01234567);

    // Get
    // Incorrect argument types
    checkNPE(() -> { // null array
        int x = (int) vh.get(null, 0);
    });
    checkCCE(() -> { // array reference class
