public void testHalfBinaryOrWithParenthesis(RUN_TYPE runType) {
    // DROOLS-6006
    final String drl1 =
            "rule R1 when\n" +
            "    Integer(intValue (< 2 || > 5))\n" +
            "then\n" +
            "end\n";

    KieSession ksession = getKieSession(runType, drl1);

    ksession.insert( 3 );
    ksession.insert( 4 );
    ksession.insert( 6 );
    assertThat(ksession.fireAllRules()).isEqualTo(1);
}

