static void testArrayWrongMethodType(Handles hs) throws Throwable {
    double[] array = new double[10];
    Arrays.fill(array, 1.0d);

    for (TestAccessMode am : testAccessModesOfType(TestAccessType.GET)) {
        // Incorrect argument types
