        assertEquals(0, query.list().size());

        query = historyService.createHistoricProcessInstanceQuery().or().processDefinitionKeyNotIn(processDefinitionKeyNotIn4).processDefinitionId("undefined");
        assertEquals(0, query.list().size());
        assertEquals(0, query.list().size());
    }
}

