    });
    checkWMTE(() -> { // value reference class
        vh.set(array, 0, Void.class);
    });
    checkWMTE(() -> { // receiver primitive class
        vh.set(0, 0, (byte)0x01);
    });
    checkWMTE(() -> { // index reference class
