code_method:
public void testTwoParamSneakyCustom()
{
    TypeFactory tf = newTypeFactory();
    JavaType type = tf.constructType(new TypeReference<TwoParam1604<String,List<Long>>>() { });
    assertEquals(TwoParam1604.class, type.getRawClass());
    assertEquals(String.class, type.containedType(0).getRawClass());
    JavaType ct = type.containedType(1);
    assertEquals(List.class, ct.getRawClass());
    assertEquals(Long.class, ct.getContentType().getRawClass());

    JavaType subtype = tf.constructSpecializedType(type, SneakyTwoParam1604.class);
    assertEquals(SneakyTwoParam1604.class, subtype.getRawClass());
    assertEquals(TwoParam1604.class, subtype.getSuperClass().getRawClass());
    assertEquals(2, subtype.containedTypeCount());

    // should properly resolve type parameters despite sneaky switching, including "unwounding"
    // `List` wrapper
    JavaType first = subtype.containedType(0);
    assertEquals(Long.class, first.getRawClass());
    JavaType second = subtype.containedType(1);
    assertEquals(String.class, second.getRawClass());
}

protected void buildRecipes() {
    var hasName = getHasName(Items.DIRT);
    var has = has(Items.DIRT);
    var items = this.registries.lookup(Registries.ITEM).get();

    // contains NBT match - should match a stone pickaxe that lost 3 durability, regardless of setting its name
    shaped()
        .pattern("XXX")
        .pattern("XXX")
        .define('X',
            partialNbt()
                .nbt(damaged())
                .items(Items.WOODEN_PICKAXE, Items.STONE_PICKAXE, Items.IRON_PICKAXE)
                .build()
        )
        .unlockedBy(hasName, has)
        .save(this.output, rk("partial_nbt_damage_only"));

    // contains NBT match - should match a named wood, stone, or iron pickaxe, regardless of damage
    shaped()
        .pattern("XXX")
        .define('X',
            partialNbt()
                .nbt(named())
                .items(Items.WOODEN_PICKAXE, Items.STONE_PICKAXE, Items.IRON_PICKAXE)
                .build()
        )
        .unlockedBy(hasName, has)
        .save(this.output, rk("partial_nbt_name_only"));

    // compound - should match named dirt or named oak logs
    shaped()
       .pattern("XXX")
       .pattern(" X ")
       .define('X', compound(
           strictNbt(named(Items.DIRT)),
           strictNbt(named(Items.OAK_LOG))
       ))
       .unlockedBy(hasName, has)
       .save(this.output, rk("compound_ingredient"));

    // strict NBT match - should match an unnamed pickaxe that lost 3 durability
    shaped()
        .pattern("XXX")
        .define('X', strictNbt(named(Items.DIAMOND_PICKAXE)))
        .unlockedBy(hasName, has)
        .save(this.output, rk("strict_nbt_ingredient"));

    // intersection - should match STONE only, [dirt, stone] + [stone, gravel]
    shaped()
        .pattern("XXX")
        .pattern("XXX")
        .pattern(" X ")
        .define('X', intersection(items, LEFT, RIGHT))
        .unlockedBy(hasName, has)
        .save(this.output, rk("intersection_ingredient"));

    // difference - should match DIRT only, [dirt, stone] - [stone, gravel]
    shaped()
       .pattern(" X ")
       .pattern("XXX")
       .pattern(" X ")
       .define('X', difference(items, LEFT, RIGHT))
       .unlockedBy(hasName, has)
       .save(this.output, rk("difference_ingredient"));
}

