@Test
void testInterrupt1() throws Exception {
    VThreadRunner.run(() -> {
        Thread me = Thread.currentThread();
        assertFalse(me.isInterrupted());
        me.interrupt();
        assertTrue(me.isInterrupted());
        Thread.interrupted();  // clear interrupt status
        assertFalse(me.isInterrupted());
        me.interrupt();
    });
}

