//-----------------------------------------------------------------------
@Test
public void now_Clock_maxYear() {
    Clock clock = Clock.fixed(MAX_INSTANT, ZoneOffset.UTC);
    LocalDateTime test = LocalDateTime.now(clock);
    assertEquals(test, MAX_DATE_TIME);
}

