        assertEquals(x, 2.0d, "getAndSetRelease double value");
    }

    // get and add, add and get
    {
        vh.set(1.0d);

        double o = (double) vh.getAndAdd(2.0d);
        assertEquals(o, 1.0d, "getAndAdd double");
